import{_ as a,o as p,c as r,a2 as c}from"./chunks/framework.EUByU7Iq.js";const g=JSON.parse('{"title":"《佛经 · 维摩诘所说经·卷上》","description":"","frontmatter":{"title":"《佛经 · 维摩诘所说经·卷上》","date":"2026-11-25T00:00:00.000Z","categories":["美文","佛经"],"collection":"《佛经 · 维摩诘所说经·卷上》","tags":["佛经","姚秦"],"poem":true,"poem_quote":false,"merged":true,"pieces":1,"author":"鸠摩罗什 译","source_book":"佛经"},"headers":[],"relativePath":"blogs/佛经·维摩诘所说经·卷上/index.md","filePath":"blogs/佛经·维摩诘所说经·卷上/index.md"}'),i={name:"blogs/佛经·维摩诘所说经·卷上/index.md"};function l(u,s,d,t,e,o){return p(),r("div",null,[...s[0]||(s[0]=[c('<h1 id="《佛经-·-维摩诘所说经·卷上》" tabindex="-1">《佛经 · 维摩诘所说经·卷上》 <a class="header-anchor" href="#《佛经-·-维摩诘所说经·卷上》" aria-label="Permalink to &quot;《佛经 · 维摩诘所说经·卷上》&quot;">​</a></h1><p class="poem-meta">姚秦 · 鸠摩罗什 译</p><p>全文 4 节 25 段，经文与白话逐段对照，收录完整。</p><div class="merged-book"><h3 id="维摩诘所说经-卷上" tabindex="-1">维摩诘所说经（卷上） <a class="header-anchor" href="#维摩诘所说经-卷上" aria-label="Permalink to &quot;维摩诘所说经（卷上）&quot;">​</a></h3><div class="sutra"><h3 class="su-sec">佛国品第一</h3><div class="su-pair"><p class="su-org">如是我闻。一时佛在毘耶离庵罗树园。与大比丘众八千人俱。菩萨三万二千。众所知识。大智本行皆悉成就。诸佛威神之所建立。为护法城受持正法。能师子吼名闻十方。众人不请友而安之。绍隆三宝能使不绝。降伏魔怨制诸外道。悉已清净永离盖缠。心常安住无碍解脱。念定总持辩才不断。布施持戒忍辱精进禅定智慧。及方便力无不具足。逮无所得不起法忍。已能随顺转不退轮。善解法相知众生根。盖诸大众得无所畏。功德智慧以修其心。相好严身色像第一。舍诸世间所有饰好。名称高远逾于须弥。深信坚固犹若金刚。法宝普照而雨甘露。于众言音微妙第一。深入缘起断诸邪见。有无二边无复余习。演法无畏犹师子吼。其所讲说乃如雷震。无有量已过量。集众法宝如海导师。了达诸法深妙之义。善知众生往来所趣及心所行。近无等等佛自在慧十力无畏十八不共。关闭一切诸恶趣门。而生五道以现其身。为大医王善疗众病。应病与药令得服行。无量功德皆成就。无量佛土皆严净。其见闻者无不蒙益。诸有所作亦不唐捐。如是一切功德皆悉具足。</p><p class="su-tra">这部经是我亲耳听佛说的。那时佛在毗耶离的庵罗树园，与八千位大比丘在一起，还有三万二千位菩萨。他们都是众所熟知的人物，卓越的智慧和根本行持都已成就，承蒙诸佛威神加持。为守护佛法城池、受持正法，能作狮子吼，名声遍闻十方。众人虽未邀请，他们仍主动结交并使其安心。他们绍隆三宝，使佛法僧三宝绵延不绝；降伏魔怨，制伏诸外道；皆已清净，永远远离五盖与缠缚。心常安住于无碍解脱，念、定、总持与辩才持续不断。布施、持戒、忍辱、精进、禅定、智慧以及方便之力，无不具足。已证得无所得、不起诸法的法忍，能随顺众生转动不退法轮。善解诸法实相，了知众生根性；覆护诸大众，使其得无所畏惧。以功德智慧修其心，以相好严饰身，色像第一。舍弃世间一切饰好，名声高远超过须弥山。深信坚固犹如金刚，以法宝普照众生，如降甘露。在众人中，言音最为微妙。深入缘起，断除邪见，于有无二边不再有余习。演说妙法，无所畏惧，犹如狮子吼；所讲说犹如雷震。无有限量而又超越限量，如大海导师集聚众法宝。了达诸法深妙之义，善知众生轮回往来所趣及心之所行。近于诸佛无等等的自在慧、十力、无畏与十八不共法。关闭一切诸恶趣之门，又生于五道以现身救度众生。作大医王，善疗众病，应病与药，令其服用遵行。无量功德皆已成就，无量佛土皆已严净；见闻者无不受益，所有作为也都不空废。这一切功德悉皆具足。</p></div><div class="su-pair"><p class="su-org">其名曰等观菩萨。不等观菩萨。等不等观菩萨。定自在王菩萨。法自在王菩萨。法相菩萨。光相菩萨。光严菩萨。大严菩萨。宝积菩萨。辩积菩萨。宝手菩萨。宝印手菩萨。常举手菩萨。常下手菩萨。常惨菩萨。喜根菩萨。喜王菩萨。辩音菩萨。虚空藏菩萨。执宝炬菩萨。宝勇菩萨。宝见菩萨。帝网菩萨。明网菩萨。无缘观菩萨。慧积菩萨。宝胜菩萨。天王菩萨。坏魔菩萨。电德菩萨。自在王菩萨。功德相严菩萨。师子吼菩萨。雷音菩萨。山相击音菩萨。香象菩萨。白香象菩萨。常精进菩萨。不休息菩萨。妙生菩萨。华严菩萨。观世音菩萨。得大势菩萨。梵网菩萨。宝杖菩萨。无胜菩萨。严土菩萨。金髻菩萨。珠髻菩萨。弥勒菩萨。文殊师利法王子菩萨。如是等三万二千人。</p><p class="su-tra">他们的名号是：等观菩萨、不等观菩萨、等不等观菩萨、定自在王菩萨、法自在王菩萨、法相菩萨、光相菩萨、光严菩萨、大严菩萨、宝积菩萨、辩积菩萨、宝手菩萨、宝印手菩萨、常举手菩萨、常下手菩萨、常惨菩萨、喜根菩萨、喜王菩萨、辩音菩萨、虚空藏菩萨、执宝炬菩萨、宝勇菩萨、宝见菩萨、帝网菩萨、明网菩萨、无缘观菩萨、慧积菩萨、宝胜菩萨、天王菩萨、坏魔菩萨、电德菩萨、自在王菩萨、功德相严菩萨、师子吼菩萨、雷音菩萨、山相击音菩萨、香象菩萨、白香象菩萨、常精进菩萨、不休息菩萨、妙生菩萨、华严菩萨、观世音菩萨、得大势菩萨、梵网菩萨、宝杖菩萨、无胜菩萨、严土菩萨、金髻菩萨、珠髻菩萨、弥勒菩萨、文殊师利法王子菩萨。像这样的菩萨共三万二千人。</p></div><div class="su-pair"><p class="su-org">复有万梵天王尸弃等。从余四天下来诣佛所而听法。复有万二千天帝。亦从余四天下来在会坐。并余大威力诸天．龙神．夜叉．干闼婆．阿修罗．迦楼罗．紧那罗．摩睺罗伽．等悉来会坐。诸比丘比丘尼优婆塞优婆夷俱来会坐。彼时佛与无量百千之众恭敬围绕而为说法。譬如须弥山王显于大海。安处众宝师子之座。蔽于一切诸来大众。</p><p class="su-tra">又有尸弃等一万位大梵天王，从其余四天下来，到佛的处所听法。又有一万二千位天帝，也从其余四天下来，参加法会而坐。还有其余有大威力的诸天，以及龙神、夜叉、干闼婆、阿修罗、迦楼罗、紧那罗、摩睺罗伽等，都来参加法会而坐。诸比丘、比丘尼、优婆塞、优婆夷也都来参加法会而坐。那时佛被无量百千大众恭敬围绕，为他们说法。佛安坐在众宝庄严的狮子座上，如须弥山王显于大海，巍然覆蔽一切前来的大众。</p></div><div class="su-pair"><p class="su-org">尔时毘耶离城有长者子。名曰宝积。与五百长者子俱。持七宝盖来诣佛所。头面礼足。各以其盖共供养佛。佛之威神令诸宝盖合成一盖。遍覆三千大千世界。而此世界广长之相悉于中现。又此三千大千世界。诸须弥山雪山。目真隣陀山摩诃目真隣陀山。香山宝山金山黑山。铁围山大铁围山。大海江河川流泉源。及日月星辰。天宫龙宫。诸尊神宫。悉现于宝盖中。又十方诸佛诸佛说法亦现于宝盖中。尔时一切大众。覩佛神力叹未曾有。合掌礼佛瞻仰尊颜目不暂舍。于是长者子宝积。即于佛前以偈颂曰。</p><p class="su-tra">那时毗耶离城有一位长者之子，名叫宝积，与五百位长者之子一同来到佛的处所，以头面礼佛足。各人用自己的宝盖共同供养佛。佛以威神之力，使诸宝盖合成一盖，遍覆三千大千世界，这个世界的广阔形貌全都显现其中。三千大千世界中的诸须弥山、雪山、目真邻陀山、大目真邻陀山、香山、宝山、金山、黑山、铁围山、大铁围山，大海、江河、川流、泉源，以及日月星辰、天宫、龙宫、诸尊神宫，都显现在宝盖中。十方诸佛及其说法也显现在宝盖中。那时一切大众目睹佛的神力，赞叹前所未有，合掌礼佛，瞻仰佛的尊颜，目光一刻不舍。于是长者之子宝积就在佛前以偈颂说道：</p></div><div class="su-pair"><p class="su-org">目净修广如青莲心净已度诸禅定久积净业称无量导众以寂故稽首既见大圣以神变普现十方无量土其中诸佛演说法于是一切悉见闻法王法力超群生常以法财施一切能善分别诸法相于第一义而不动已于诸法得自在是故稽首此法王说法不有亦不无以因缘故诸法生无我无造无受者善恶之业亦不亡始在佛树力降魔得甘露灭觉道成已无心意无受行而悉摧伏诸外道三转法轮于大千其轮本来常清净天人得道此为证三宝于是现世间以斯妙法济群生一受不退常寂然度老病死大医王当礼法海德无边毁誉不动如须弥于善不善等以慈心行平等如虚空孰闻人宝不敬承今奉世尊此微盖于中现我三千界诸天龙神所居宫干闼婆等及夜叉悉见世间诸所有十力哀现是化变众覩希有皆叹佛今我稽首三界尊大圣法王众所归净心观佛靡不欣各见世尊在其前斯则神力不共法佛以一音演说法众生随类各得解皆谓世尊同其语斯则神力不共法佛以一音演说法众生各各随所解普得受行获其利斯则神力不共法佛以一音演说法或有恐畏或欢喜或生厌离或断疑斯则神力不共法稽首十力大精进稽首已得无所畏稽首住于不共法稽首一切大导师稽首能断众结缚稽首已到于彼岸稽首能度诸世间稽首永离生死道悉知众生来去相善于诸法得解脱不著世间如莲华常善入于空寂行达诸法相无罣碍稽首如空无所依</p><p class="su-tra">“目清净而修广，犹如青莲；心清净，已超越诸禅定；久积净业，名为无量；引导众生归于寂灭，因此稽首。既见大圣施展神变，普现十方无量佛土；其中诸佛演说妙法，这一切都得以见闻。法王的神力超越群生，常以法财布施一切；善于分别诸法实相，于第一义而不动摇；已于诸法得自在，因此稽首此法王。说法既不著有，也不著无；以因缘故，诸法生起；无我、无造作、无受者，善恶之业也不会消亡。始在菩提树下以力降魔，得甘露而灭度，觉道得以成就；已无心意，也无所受所行，而悉能摧伏诸外道。于大千世界三转法轮，其轮本来常清净；天人得道，以此作为证明，三宝于是显现世间；以这妙法济度群生，一经受持便不退转，常归寂然；是度脱老病死的大医王。应当礼敬法海，功德无边；毁誉不动，犹如须弥山；于善与不善同等以慈，心行平等如虚空；有谁听闻人中之宝而不恭敬承奉？今奉世尊此微小宝盖；其中现出三千世界，诸天龙神所居的宫阙，干闼婆等及夜叉，世间一切所有都得以看见。十力世尊慈悲显现这些变化，大众目睹稀有景象，都赞叹佛。今我稽首三界之尊，大圣法王，众所归依；以净心观佛，无不喜欢，各见世尊在自己面前。这是佛不共的神力：佛以一音演说妙法，众生随类各自得解，都说世尊说的是自己的语言。这是佛不共的神力：佛以一音演说妙法，众生各各随所理解，普遍受持修行而获其利益。这是佛不共的神力：佛以一音演说妙法，或有恐惧，或有欢喜，或生厌离，或断疑惑。这是佛不共的神力。稽首十力、大精进，稽首已得无所畏，稽首住于不共法，稽首一切大导师，稽首能断众结缚，稽首已到彼岸，稽首能度诸世间，稽首永离生死之道；悉知众生来去之相，善于诸法而得解脱，不著世间如莲华；常善入于空寂之行，了达诸法实相而无挂碍；稽首如虚空而无所依。”</p></div><div class="su-pair"><p class="su-org">尔时长者子宝积。说此偈已白佛言。世尊。是五百长者子。皆已发阿耨多罗三藐三菩提心。愿闻得佛国土清净。唯愿世尊。说诸菩萨净土之行。佛言。善哉宝积。乃能为诸菩萨问于如来净土之行。谛听谛听善思念之。当为汝说。于是宝积及五百长者子。受教而听。佛言。宝积。众生之类是菩萨佛土。所以者何。菩萨随所化众生而取佛土。随所调伏众生而取佛土。随诸众生应以何国入佛智慧而取佛土。随诸众生应以何国起菩萨根而取佛土。所以者何。菩萨取于净国。皆为饶益诸众生故。譬如有人欲于空地造立宫室随意无碍。若于虚空终不能成。菩萨如是。为成就众生故愿取佛国。愿取佛国者非于空也。宝积。当知直心是菩萨净土。菩萨成佛时不谄众生来生其国。深心是菩萨净土。菩萨成佛时具足功德众生来生其国。菩提心是菩萨净土。菩萨成佛时大乘众生来生其国。布施是菩萨净土。菩萨成佛时一切能舍众生来生其国。持戒是菩萨净土。菩萨成佛时行十善道满愿众生来生其国。忍辱是菩萨净土。菩萨成佛时三十二相庄严众生来生其国。精进是菩萨净土。菩萨成佛时勤修一切功德众生来生其国。禅定是菩萨净土。菩萨成佛时摄心不乱众生来生其国。智慧是菩萨净土。菩萨成佛时正定众生来生其国。四无量心是菩萨净土。菩萨成佛时成就慈悲喜舍众生来生其国。四摄法是菩萨净土。菩萨成佛时解脱所摄众生来生其国。方便是菩萨净土。菩萨成佛时于一切法方便无碍众生来生其国。三十七道品是菩萨净土。菩萨成佛时念处正勤神足根力觉道众生来生其国。回向心是菩萨净土。菩萨成佛时得一切具足功德国土。说除八难是菩萨净土。菩萨成佛时国土无有三恶八难。自守戒行不讥彼阙是菩萨净土。菩萨成佛时国土无有犯禁之名。十善是菩萨净土。菩萨成佛时命不中夭。大富梵行所言诚谛。常以软语眷属不离。善和诤讼言必饶益。不嫉不恚正见众生来生其国。如是宝积。菩萨随其直心则能发行。随其发行则得深心。随其深心。则意调伏。随意调伏则如说行。随如说行则能回向。随其回向则有方便。随其方便则成就众生。随成就众生则佛土净。随佛土净则说法净。随说法净则智慧净。随智慧净则其心净。随其心净则一切功德净。是故宝积。若菩萨欲得净土当净其心。随其心净则佛土净。</p><p class="su-tra">这时长者之子宝积说完此偈，便对佛说：“世尊，这五百位长者之子都已发阿耨多罗三藐三菩提心，愿听闻如何获得清净佛土。唯愿世尊宣说诸菩萨净土之行。”佛说：“好啊，宝积！你能为诸菩萨请问如来的净土之行。仔细听，好好思维，当为你们说。”于是宝积及五百位长者之子受教而听。佛说：“宝积，众生的种类就是菩萨的佛土。为什么呢？菩萨随所教化的众生而取佛土，随所调伏的众生而取佛土，随众生应以何种国土而入佛智慧而取佛土，随众生应以何种国土起菩萨根而取佛土。为什么呢？菩萨取于净国，都是为了饶益诸众生。譬如有人想在空地建造宫室，可以随意而无障碍；若在虚空，终究不能建成。菩萨也是如此，为成就众生而愿取佛国；愿取佛国，并不是在虚空中取。宝积，当知直心是菩萨净土，菩萨成佛时，不谄的众生来生其国；深心是菩萨净土，菩萨成佛时，具足功德的众生来生其国；菩提心是菩萨净土，菩萨成佛时，大乘众生来生其国；布施是菩萨净土，菩萨成佛时，一切能舍的众生来生其国；持戒是菩萨净土，菩萨成佛时，行十善道、满愿的众生来生其国；忍辱是菩萨净土，菩萨成佛时，以三十二相庄严的众生来生其国；精进是菩萨净土，菩萨成佛时，勤修一切功德的众生来生其国；禅定是菩萨净土，菩萨成佛时，摄心不乱的众生来生其国；智慧是菩萨净土，菩萨成佛时，正定众生来生其国；四无量心是菩萨净土，菩萨成佛时，成就慈悲喜舍的众生来生其国；四摄法是菩萨净土，菩萨成佛时，为解脱所摄的众生来生其国；方便是菩萨净土，菩萨成佛时，于一切法方便无碍的众生来生其国；三十七道品是菩萨净土，菩萨成佛时，修习念处、正勤、神足、根、力、觉、道的众生来生其国；回向心是菩萨净土，菩萨成佛时，得一切具足功德的国土；宣说除去八难是菩萨净土，菩萨成佛时，国土无有三恶道及八种灾难；自守戒行而不讥笑他人的缺失，是菩萨净土，菩萨成佛时，国土无有犯禁之名；十善是菩萨净土，菩萨成佛时，众生不中途夭折，大富而有梵行，所言诚实真实，常以柔和之语而使眷属不离，善于调和诤讼，言语必定有益，不嫉妒、不嗔恚、持正见的众生来生其国。如是，宝积，菩萨随其直心则能发行，随其发行则得深心，随其深心则意调伏，随其意调伏则如说而行，随其如说而行则能回向，随其回向则有方便，随其方便则成就众生，随成就众生则佛土净，随佛土净则说法净，随说法净则智慧净，随智慧净则其心净，随其心净则一切功德净。所以，宝积，若菩萨欲得净土，当净其心；随其心净，则佛土净。”</p></div><div class="su-pair"><p class="su-org">尔时舍利弗。承佛威神作是念。若菩萨心净则佛土净者。我世尊本为菩萨时意岂不净。而是佛土不净若此。佛知其念即告之言。于意云何。日月岂不净耶。而盲者不见。对曰不也。世尊。是盲者过非日月咎。舍利弗。众生罪故不见如来佛土严净。非如来咎。舍利弗。我此土净而汝不见。尔时螺髻梵王语舍利弗。勿作是意。谓此佛土以为不净。所以者何。我见释迦牟尼佛土清净。譬如自在天宫。舍利弗言。我见此土。丘陵坑坎荆蕀沙砾。土石诸山秽恶充满。螺髻梵言。仁者心有高下。不依佛慧故。见此土为不净耳。舍利弗。菩萨于一切众生。悉皆平等。深心清净。依佛智慧则能见此佛土清净。</p><p class="su-tra">这时舍利弗承佛威神，心中作念：若菩萨心净则佛土净，那么世尊昔日为菩萨时，意念岂有不净，而佛土却不净到如此地步？佛知道他的念头，立即告诉他说：“你怎么看？日月难道不净吗？而盲人看不见。”舍利弗回答：“不是的，世尊。这是盲人的过失，并非日月的过错。”佛说：“舍利弗，众生因罪业而不见如来佛土的庄严清净，并非如来的过错。舍利弗，我这佛土本来是清净的，而你看不见。”这时螺髻梵王对舍利弗说：“不要这样想，认为此佛土不净。为什么呢？我见释迦牟尼佛土清净，譬如自在天宫。”舍利弗说：“我看见此土，丘陵、坑坎、荆棘、沙砾，土石诸山，秽恶充满。”螺髻梵王说：“仁者心有高下，不依佛的智慧，所以见此土为不净。舍利弗，菩萨于一切众生悉皆平等，深心清净，依佛智慧则能见此佛土清净。”</p></div><div class="su-pair"><p class="su-org">于是佛以足指按地。即时三千大千世界若干百千珍宝严饰。譬如宝庄严佛无量功德宝庄严土。一切大众叹未曾有。而皆自见坐宝莲华。佛告舍利弗。汝且观是佛土严净。舍利弗言。唯然世尊。本所不见。本所不闻。今佛国土严净悉现。佛语舍利弗。我佛国土常净若此。为欲度斯下劣人故。示是众恶不净土耳。譬如诸天共宝器食随其福德饭色有异。如是舍利弗。若人心净便见此土功德庄严。当佛现此国土严净之时。宝积所将五百长者子皆得无生法忍。八万四千人皆发阿耨多罗三藐三菩提心。佛摄神足。于是世界还复如故。求声闻乘三万二千天及人。知有为法皆悉无常。远尘离垢得法眼净。八千比丘不受诸法漏尽意解。</p><p class="su-tra">于是佛以足指按地，即时三千大千世界便有若干百千珍宝严饰，譬如以无量功德宝庄严的佛土。一切大众赞叹前所未有，都各自看见坐在宝莲华上。佛告诉舍利弗：“你且观此佛土，多么庄严清净。”舍利弗说：“唯然，世尊。这本来是我不曾见、不曾闻的，如今佛国土的庄严清净全都显现了。”佛对舍利弗说：“我的佛土常像这样清净，为要度脱这些下劣的人，才示现这充满众恶的不净之相。譬如诸天共用宝器进食，随其福德不同，饭的颜色也有差异。如是，舍利弗，若人心净，便能见此土的功德庄严。”当佛显现此国土庄严清净时，宝积所带的五百位长者之子都得了无生法忍，八万四千人都发阿耨多罗三藐三菩提心。佛收起神足之力，于是世界还复如故。三万二千位求声闻乘的天人，知道有为法皆悉无常，远离尘垢，得法眼清净；八千位比丘不受诸法，漏尽而心得解脱。</p></div><h3 class="su-sec">方便品第二</h3><div class="su-pair"><p class="su-org">尔时毘耶离大城中有长者名维摩诘。已曾供养无量诸佛深植善本。得无生忍。辩才无碍。游戏神通逮诸总持。获无所畏降魔劳怨。入深法门善于智度。通达方便大愿成就。明了众生心之所趣。又能分别诸根利钝。久于佛道心已纯淑决定大乘。诸有所作能善思量。住佛威仪心大如海。诸佛咨嗟弟子。释梵世主所敬。欲度人故以善方便居毘耶离。资财无量摄诸贫民。奉戒清净摄诸毁禁。以忍调行摄诸恚怒。以大精进摄诸懈怠。一心禅寂摄诸乱意。以决定慧摄诸无智。虽为白衣奉持沙门清净律行。虽处居家不著三界。示有妻子常修梵行。现有眷属常乐远离。虽服宝饰而以相好严身。虽复饮食而以禅悦为味。若至博弈戏处辄以度人。受诸异道不毁正信。虽明世典常乐佛法。一切见敬为供养中最。执持正法摄诸长幼。一切治生谐偶虽获俗利不以喜悦。游诸四衢饶益众生。入治政法救护一切。入讲论处导以大乘。入诸学堂诱开童蒙。入诸婬舍示欲之过。入诸酒肆能立其志。若在长者长者中尊为说胜法。若在居士居士中尊断其贪著。若在刹利刹利中尊教以忍辱。若在婆罗门婆罗门中尊除其我慢。若在大臣大臣中尊教以正法。若在王子王子中尊示以忠孝。若在内官内官中尊化政宫女。若在庶民庶民中尊令兴福力。若在梵天梵天中尊诲以胜慧。若在帝释帝释中尊示现无常。若在护世护世中尊护诸众生。长者维摩诘。以如是等无量方便饶益众生。其以方便现身有疾。以其疾故。国王大臣长者居士婆罗门等。及诸王子并余官属。无数千人皆往问疾。其往者。维摩诘因以身疾广为说法。诸仁者。是身无常无强无力无坚。速朽之法不可信也。为苦为恼众病所集。诸仁者。如此身明智者所不怙。是身如聚沫不可撮摩。是身如泡不得久立。是身如炎从渴爱生。是身如芭蕉中无有坚。是身如幻从颠倒起。是身如梦为虚妄见。是身如影从业缘现。是身如响属诸因缘。是身如浮云须臾变灭。是身如电念念不住。是身无主为如地。是身无我为如火。是身无寿为如风。是身无人为如水。是身不实四大为家。是身为空离我我所。是身无知如草木瓦砾。是身无作风力所转。是身不净秽恶充满。是身为虚伪。虽假以澡浴衣食必归磨灭。是身为灾百一病恼。是身如丘井为老所逼。是身无定为要当死。是身如毒蛇如怨贼如空聚。阴界诸入所共合成。诸仁者。此可患厌当乐佛身。所以者何。佛身者即法身也。从无量功德智慧生。从戒定慧解脱解脱知见生。从慈悲喜舍生。从布施持戒忍辱柔和勤行精进禅定解脱三昧多闻智慧诸波罗蜜生。从方便生。从六通生。从三明生。从三十七道品生。从止观生。从十力四无所畏十八不共法生。从断一切不善法集一切善法生。从真实生。从不放逸生。从如是无量清净法生如来身。诸仁者。欲得佛身断一切众生病者。当发阿耨多罗三藐三菩提心。如是长者维摩诘。为诸问疾者如应说法。令无数千人皆发阿耨多罗三藐三菩提心。</p><p class="su-tra">这时毗耶离大城中有一位长者，名叫维摩诘。他曾供养无量诸佛，深植善根，得无生法忍，辩才无碍，游戏神通，逮得诸总持，获无所畏，降伏魔劳与怨敌。他深入微妙法门，善于智慧度，通达方便，大愿成就，明了众生心之所趣，又能分别诸根利钝。久修佛道，心已纯正，决定大乘；诸有所作，都能善加思量。住于佛的威仪，心大如海。诸佛赞叹他，弟子、帝释、梵天与世间诸主都敬奉他。为度化众生，他以善方便居住在毗耶离。以无量资财摄受贫民，以清净持戒摄受毁禁之人，以忍辱调和之行摄受嗔怒之人，以大精进摄受懈怠之人，以一心禅寂摄受乱意之人，以决定慧摄受无智之人。虽为白衣，却奉持沙门清净律行；虽处居家，却不著三界；示现有妻子，却常修梵行；现有眷属，却常乐远离；虽服宝饰，却以相好严饰自身；虽复饮食，却以禅悦为味。若到赌博游戏之处，就借此度人；与诸异道往来，却不毁坏正信；虽通晓世典，却常乐佛法。一切见到他的人都恭敬他，他是一切供养中最上的对象。他执持正法，摄受诸长幼；经营各种生计、料理世俗事务，虽获世俗利益，心中却不喜悦。他游历四通大道，饶益众生；进入治理政事与法律之处，救护一切；进入讲论之处，以大乘引导；进入学堂，启发童蒙；进入淫舍，示现欲望的过失；进入酒肆，能确立人的志趣。在长者之中，他受尊重，为其说殊胜之法；在居士之中，他受尊重，断除其贪著；在刹利之中，他受尊重，教以忍辱；在婆罗门之中，他受尊重，除其我慢；在大臣之中，他受尊重，教以正法；在王子之中，他受尊重，示以忠孝；在内官之中，他受尊重，教化宫女；在庶民之中，他受尊重，令其兴起福德之力；在梵天之中，他受尊重，教诲殊胜智慧；在帝释之中，他受尊重，示现无常；在护世天王之中，他受尊重，护持众生。长者维摩诘以如是等无量方便饶益众生。他以方便示现有病，因其患病，国王、大臣、长者、居士、婆罗门等，以及诸王子和其余官属，无数千人都前往问疾。前往之人，维摩诘便因其疾病而广为说法：“诸仁者，这身体无常、无力、不坚，是迅速朽坏之法，不可信也。它为苦所迫，为烦恼所扰，是众病聚集之处。诸仁者，这样的身体，明智之人是不会依恃的。这身体如聚沫，不可撮取摩弄；如水泡，不能长久停立；如阳焰，由渴爱而生；如芭蕉，中间没有坚实；如幻术，由颠倒而生；如梦境，是虚妄所见；如影子，从业缘而显现；如回响，属于各种因缘；如浮云，片刻便变灭；如闪电，念念不住。这身体无主，犹如大地；无我，犹如火焰；无寿，犹如风；无人，犹如水；不实，以四大为家；为空，远离我及我所；无知，犹如草木瓦砾；无有造作，为风力所转；不净，秽恶充满；虚伪，虽假以洗浴、衣服、饮食，终究归于磨灭。这身体是灾患，有百一种病恼；如丘井，为衰老所逼迫；没有决定性，终当死亡；如毒蛇，如怨贼，如空聚，由五阴、十八界、十二入共同合成。诸仁者，此身可患可厌，应当乐于佛身。为什么呢？佛身就是法身，从无量功德智慧而生，从戒、定、慧、解脱、解脱知见而生，从慈悲喜舍而生，从布施、持戒、忍辱、柔和、勤行、精进、禅定、解脱、三昧、多闻、智慧及诸波罗蜜而生，从方便而生，从六通而生，从三明而生，从三十七道品而生，从止观而生，从十力、四无所畏、十八不共法而生，从断除一切不善法、集聚一切善法而生，从真实而生，从不放逸而生。如来之身从这些无量清净法而生。诸仁者，若想得到佛身、断除一切众生的疾病，就应发阿耨多罗三藐三菩提心。”长者维摩诘就这样为诸问疾者应机说法，令无数千人皆发阿耨多罗三藐三菩提心。</p></div><h3 class="su-sec">弟子品第三</h3><div class="su-pair"><p class="su-org">尔时长者维摩诘自念。寝疾于床。世尊大慈宁不垂愍。佛知其意。即告舍利弗。汝行诣维摩诘问疾。舍利弗白佛言。世尊。我不堪任诣彼问疾。所以者何。忆念我昔曾于林中宴坐树下。时维摩诘来谓我言。唯舍利弗。不必是坐为宴坐也。夫宴坐者。不于三界现身意。是为宴坐。不起灭定而现诸威仪。是为宴坐。不舍道法而现凡夫事。是为宴坐。心不住内亦不在外。是为宴坐。于诸见不动而修行三十七品。是为宴坐。不断烦恼而入涅槃。是为宴坐。若能如是坐者。佛所印可。时我世尊。闻说是语默然而止不能加报。故我不任诣彼问疾。</p><p class="su-tra">这时长者维摩诘自己心想：我卧病于床，世尊大慈，难道不怜愍我吗？佛知道他的心意，便告诉舍利弗：“你到维摩诘那里问疾。”舍利弗对佛说：“世尊，我不能胜任去向他问疾。为什么呢？回忆我从前曾在林中宴坐于树下，维摩诘来对我说：‘唯舍利弗，不必这样才叫宴坐。宴坐，是不于三界显现身与意；是不起灭尽定而显现各种威仪；是不舍弃道法而显现凡夫之事；是心不住于内也不住于外；是于诸见不动而修行三十七道品；是不断烦恼而入涅槃。若能这样坐，才为佛所印可。’世尊，我听了这话，默然无语，不能回答，所以不能胜任去向他问疾。”</p></div><div class="su-pair"><p class="su-org">佛告大目犍连。汝行诣维摩诘问疾。目连白佛言。世尊。我不堪任诣彼问疾。所以者何。忆念我昔入毘耶离大城。于里巷中为诸居士说法。时维摩诘来谓我言。唯大目连。为白衣居士说法。不当如仁者所说。夫说法者当如法说。法无众生离众生垢故。法无有我离我垢故。法无寿命离生死故。法无有人前后际断故。法常寂然灭诸相故。法离于相无所缘故。法无名字言语断故。法无有说离觉观故。法无形相如虚空故。法无戏论毕竟空故。法无我所离我所故。法无分别离诸识故。法无有比无相待故。法不属因不在缘故。法同法性入诸法故。法随于如无所随故。法住实际诸边不动故。法无动摇不依六尘故。法无去来常不住故。法顺空随无相应无作。法离好丑。法无增损。法无生灭。法无所归。法过眼耳鼻舌身心。法无高下。法常住不动。法离一切观行。唯大目连。法相如是岂可说乎。夫说法者无说无示。其听法者无闻无得。譬如幻士为幻人说法当建是意而为说法。当了众生根有利钝。善于知见无所罣碍。以大悲心赞于大乘。念报佛恩不断三宝。然后说法。维摩诘说是法时。八百居士发阿耨多罗三藐三菩提心。我无此辩。是故不任诣彼问疾。</p><p class="su-tra">佛告诉大目犍连：“你到维摩诘那里问疾。”目连对佛说：“世尊，我不能胜任去向他问疾。为什么呢？回忆我从前进入毗耶离大城，在里巷中为诸居士说法，维摩诘来对我说：‘唯大目连，为白衣居士说法，不应像你这样说。说法的人应当如法而说。法无众生，因为远离众生之垢；法无我，因为远离我之垢；法无寿命，因为远离生死；法无有人，因为前后际断；法常寂然，因为灭除诸相；法离于相，因为无所缘；法无名字，因为言语道断；法无有说，因为远离觉观；法无形相，如虚空；法无戏论，毕竟空；法无我所，因为远离我所；法无分别，因为远离诸识；法无有比，因为无相待；法不属因，也不在缘；法同于法性，入于诸法；法随于如，因为无所随；法住于实际，因为诸边不动；法无动摇，因为不依六尘；法无去来，因为常不住；法顺于空，随于无住，相应于无作；法离好丑；法无增减；法无生灭；法无所归；法超过眼、耳、鼻、舌、身、心；法无高下；法常住不动；法离一切观行。唯大目连，法相如此，难道可以言说吗？说法的人无说无示，听法的人无闻无得。譬如幻术师为幻化的人说法，当建立这样的意念而说法；应当了知众生根性有利钝，善于知见而无所挂碍，以大悲心赞叹大乘，念报佛恩、不断三宝，然后说法。’维摩诘说此法时，八百位居士发阿耨多罗三藐三菩提心。我没有这样的辩才，所以不能胜任去向他问疾。”</p></div><div class="su-pair"><p class="su-org">佛告大迦叶。汝行诣维摩诘问疾。迦叶白佛言。世尊。我不堪任诣彼问疾。所以者何。忆念我昔于贫里而行乞。时维摩诘来谓我言。唯大迦叶。有慈悲心而不能普。舍豪富从贫乞。迦叶。住平等法应次行乞食。为不食故应行乞食。为坏和合相故应取揣食。为不受故应受彼食。以空聚想入于聚落。所见色与盲等。所闻声与响等。所嗅香与风等。所食味不分别。受诸触如智证。知诸法如幻相无自性无他性。本自不然今则无灭。迦叶。若能不舍八邪入八解脱。以邪相入正法。以一食施一切。供养诸佛及众贤圣。然后可食。如是食者非有烦恼非离烦恼。非入定意非起定意。非住世间非住涅槃。其有施者无大福无小福。不为益不为损。是为正入佛道不依声闻。迦叶。若如是食为不空食人之施也。时我世尊。闻说是语得未曾有。即于一切菩萨深起敬心。复作是念。斯有家名辩才智慧乃能如是。其谁闻此不发阿耨多罗三藐三菩提心。我从是来不复劝人以声闻辟支佛行。是故不任诣彼问疾。</p><p class="su-tra">佛告诉大迦叶：“你到维摩诘那里问疾。”迦叶对佛说：“世尊，我不能胜任去向他问疾。为什么呢？回忆我从前在贫民聚居之处行乞，维摩诘来对我说：‘唯大迦叶，你有慈悲心，却不能普济众生，所以舍弃豪富之家而向贫穷者乞食。迦叶，住于平等法，应次第行乞；为不食之故，应行乞食；为破除和合之相，应取一小把饭；为不受之故，应接受彼食。以空聚之想进入聚落，所见色与盲者所见相等，所闻声与回响相等，所嗅香与风相等，所食味不加分别，所受诸触如智慧亲证，知诸法如幻化之相，无自性、无他性，本来不生，如今也无灭。迦叶，若能不舍八邪而入八解脱，以邪相入正法，以一食布施一切，供养诸佛及众贤圣，然后才可以食。这样进食，不是有烦恼，也不是离烦恼；不是入定，也不是出定；不是住于世间，也不是住于涅槃。施者无大福，也无小福；不为利益，也不为损害。这是正入佛道，不依声闻。迦叶，若这样进食，才不空费施主之食。’世尊，我听了这话，得未曾有，便对一切菩萨深起敬心，又这样想：这个有家室之名的人，竟有这样的辩才智慧。有谁听了而不发阿耨多罗三藐三菩提心呢？我从那时起，不再劝人修声闻、辟支佛行，所以不能胜任去向他问疾。”</p></div><div class="su-pair"><p class="su-org">佛告须菩提。汝行诣维摩诘问疾。须菩提白佛言。世尊。我不堪任诣彼问疾。所以者何。忆念我昔入其舍从乞食。时维摩诘取我钵盛满饭。谓我言。唯须菩提。若能于食等者诸法亦等。诸法等者于食亦等。如是行乞乃可取食。若须菩提。不断婬怒痴亦不与俱。不坏于身而随一相。不灭痴爱起于明脱。以五逆相而得解脱。亦不解不缚。不见四谛非不见谛。非得果非不得果。非凡夫非离凡夫法。非圣人非不圣人。虽成就一切法而离诸法相。乃可取食。若须菩提。不见佛不闻法。彼外道六师。富兰那迦叶。末伽梨拘赊梨子。删阇夜毘罗胝子。阿耆多翅舍钦婆罗。迦罗鸠驮迦旃延。尼犍陀若提子等。是汝之师因其出家。彼师所堕汝亦随堕。乃可取食。若须菩提。入诸邪见不到彼岸。住于八难不得无难。同于烦恼离清净法。汝得无诤三昧。一切众生亦得是定。其施汝者不名福田。供养汝者堕三恶道。为与众魔共一手作诸劳侣。汝与众魔及诸尘劳等无有异。于一切众生而有怨心。谤诸佛毁于法不入众数。终不得灭度。汝若如是乃可取食。时我世尊。闻此语茫然不识是何言。不知以何答。便置钵欲出其舍。维摩诘言。唯须菩提取钵勿惧。于意云何。如来所作化人。若以是事诘。宁有惧不。我言。不也。维摩诘言。一切诸法如幻化相。汝今不应有所惧也。所以者何。一切言说不离是相。至于智者不著文字故无所惧。何以故。文字性离无有文字。是则解脱。解脱相者则诸法也。维摩诘说是法时。二百天子得法眼净。故我不任诣彼问疾。</p><p class="su-tra">佛告诉须菩提：“你到维摩诘那里问疾。”须菩提对佛说：“世尊，我不能胜任去向他问疾。为什么呢？回忆我从前进入他的住处乞食，维摩诘取我的钵，盛满饭，对我说：‘唯须菩提，若能于食平等，诸法也平等；诸法平等，于食也平等。这样行乞，才可以取食。若须菩提，不断淫、怒、痴，也不与它们相俱；不毁坏身体而随于一相；不灭痴爱而起于明脱；以五逆之相而得解脱，既不解脱也不束缚；不见四谛，也并非不见谛；非得果，也并非不得果；非凡夫，也非离凡夫法；非圣人，也非不是圣人；虽成就一切法，却离于诸法相，才可以取食。若须菩提，不见佛、不闻法，彼外道六师——富兰那迦叶、末伽梨拘赊梨子、删阇夜毗罗胝子、阿耆多翅舍钦婆罗、迦罗鸠驮迦旃延、尼犍陀若提子等，是你的师父，你因他们而出家；他们所堕之处，你也随堕，才可以取食。若须菩提，进入诸邪见而不到彼岸，住于八难而不得无难，同于烦恼而离于清净法；你得无诤三昧，一切众生也应得此定；施与你的人不名为福田，供养你的人堕于三恶道；你与众魔共一手而作诸劳侣，与众魔及诸尘劳没有差异；你对一切众生而有怨心，诽谤诸佛、毁坏正法，不入众数，终究不得灭度。你若如此，才可以取食。’世尊，我听了这话，茫然不知他说的是什么，也不知用什么回答，便放下钵想离开他的住处。维摩诘说：‘唯须菩提，取钵不要害怕。你怎么看？如来所作的化人，若用这些话责问他，难道会有恐惧吗？’我说：‘不会。’维摩诘说：‘一切诸法都如幻化之相，你现在不应有所恐惧。为什么呢？一切言说不离此相，至于智者不著文字，所以无所恐惧。为什么呢？文字之性远离文字，无有文字，这便是解脱。解脱之相就是诸法。’维摩诘说此法时，二百位天子得法眼清净，所以不能胜任去向他问疾。”</p></div><div class="su-pair"><p class="su-org">佛告富楼那弥多罗尼子。汝行诣维摩诘问疾。富楼那白佛言。世尊。我不堪任诣彼问疾。所以者何。忆念我昔于大林中在一树下。为诸新学比丘说法。时维摩诘来谓我言。唯富楼那。先当入定观此人心然后说法。无以秽食置于宝器。当知是比丘心之所念。无以琉璃同彼水精。汝不能知众生根源。无得发起以小乘法。彼自无疮勿伤之也。欲行大道莫示小径。无以大海内于牛迹。无以日光等彼萤火。富楼那。此比丘久发大乘心。中忘此意。如何以小乘法而教导之。我观小乘智慧微浅犹如盲人。不能分别一切众生根之利钝。时维摩诘即入三昧。令此比丘自识宿命。曾于五百佛所植众德本。回向阿耨多罗三藐三菩提。即时豁然还得本心。于是诸比丘稽首礼维摩诘足。时维摩诘因为说法。于阿耨多罗三藐三菩提不复退转。我念声闻不观人根不应说法。是故不任诣彼问疾。</p><p class="su-tra">佛告诉富楼那弥多罗尼子：“你到维摩诘那里问疾。”富楼那对佛说：“世尊，我不能胜任去向他问疾。为什么呢？回忆我从前在大林中一树下，为诸新学比丘说法，维摩诘来对我说：‘唯富楼那，先当入定观察此人的心，然后说法；不要把秽食放在宝器中。当知这比丘心之所念，不要把琉璃当作水晶。你不知众生的根性根源，不得发起小乘之法。他自己没有疮，不要伤害他。欲行大道，不要指示小径；不要把大海纳入牛蹄印中；不要把日光与萤火相等。富楼那，这比丘久已发大乘心，中途忘了此意，如何用小乘法教导他呢？我看小乘智慧微浅，犹如盲人，不能分别一切众生根性的利钝。’维摩诘随即进入三昧，令这比丘自己识知宿命。他曾在五百位佛处植众德本，回向阿耨多罗三藐三菩提，顿时豁然开朗，恢复本心。于是诸比丘稽首礼维摩诘足。维摩诘因此为他们说法，他们于阿耨多罗三藐三菩提不再退转。我想，声闻不观察人的根性，不应说法，所以不能胜任去向他问疾。”</p></div><div class="su-pair"><p class="su-org">佛告摩诃迦旃延。汝行诣维摩诘问疾。迦旃延白佛言。世尊。我不堪任诣彼问疾。所以者何。忆念昔者佛为诸比丘略说法要。我即于后敷演其义。谓无常义苦义空义无我义寂灭义。时维摩诘来谓我言。唯迦旃延。无以生灭心行说实相法。迦旃延。诸法毕竟不生不灭。是无常义。五受阴洞达空无所起。是苦义。诸法究竟无所有。是空义。于我无我而不二。是无我义。法本不然今则无灭。是寂灭义。说是法时彼诸比丘心得解脱。故我不任诣彼问疾。</p><p class="su-tra">佛告诉摩诃迦旃延：“你到维摩诘那里问疾。”迦旃延对佛说：“世尊，我不能胜任去向他问疾。为什么呢？回忆从前佛为诸比丘略说法要，我随后敷演其义，讲无常义、苦义、空义、无我义、寂灭义。维摩诘来对我说：‘唯迦旃延，不要以生灭心来宣说实相法。迦旃延，诸法毕竟不生不灭，这是无常义；五受阴洞达空而无所起，这是苦义；诸法究竟无所有，这是空义；于我、无我而不二，这是无我义；法本不生，如今也无灭，这是寂灭义。’说此法时，彼诸比丘心得解脱，所以不能胜任去向他问疾。”</p></div><div class="su-pair"><p class="su-org">佛告阿那律。汝行诣维摩诘问疾。阿那律白佛言。世尊。我不堪任诣彼问疾。所以者何。忆念我昔于一处经行。时有梵王名曰严净。与万梵俱放净光明来诣我所。稽首作礼问我言。几何阿那律天眼所见。我即答言。仁者。吾见此释迦牟尼佛土三千大千世界。如观掌中庵摩勒果。时维摩诘来谓我言。唯阿那律。天眼所见为作相耶。无作相耶。假使作相则与外道五通等。若无作相即是无为不应有见。世尊。我时默然。彼诸梵闻其言得未曾有。即为作礼而问曰。世孰有真天眼者。维摩诘言。有佛世尊得真天眼。常在三昧悉见诸佛国不以二相。于是严净梵王及其眷属五百梵天。皆发阿耨多罗三藐三菩提心。礼维摩诘足已忽然不现。故我不任诣彼问疾。</p><p class="su-tra">佛告诉阿那律：“你到维摩诘那里问疾。”阿那律对佛说：“世尊，我不能胜任去向他问疾。为什么呢？回忆我从前在一处经行，时有位梵王名叫严净，与一万位梵天眷属放着清净光明来到我这里，稽首作礼，问我：‘阿那律，你的天眼所见有多少？’我回答说：‘仁者，我看见这释迦牟尼佛土三千大千世界，如同观看掌中的庵摩勒果。’维摩诘来对我说：‘唯阿那律，天眼所见，是作相而见，还是无作相而见？假使作相，就与外道的五通相等；若无作相，即是无为，不应有所见。’世尊，我当时默然。彼诸梵天听了这话，得未曾有，便向他作礼而问：‘世间谁有真正的天眼？’维摩诘说：‘有佛世尊得真正的天眼，常在三昧中悉见诸佛国土，不以二相而见。’于是严净梵王及其眷属五百位梵天，都发阿耨多罗三藐三菩提心，礼维摩诘足后，忽然不现，所以不能胜任去向他问疾。”</p></div><div class="su-pair"><p class="su-org">佛告优波离。汝行诣维摩诘问疾。优波离白佛言。世尊。我不堪任诣彼问疾。所以者何。忆念昔者有二比丘。犯律行以为耻。不敢问佛。来问我言。唯优波离。我等犯律诚以为耻。不敢问佛。愿解疑悔得免斯咎。我即为其如法解说。时维摩诘来谓我言。唯优波离。无重增此二比丘罪。当直除灭勿扰其心。所以者何。彼罪性不在内不在外不在中间。如佛所说。心垢故众生垢。心净故众生净。心亦不在内不在外不在中间。如其心然。罪垢亦然。诸法亦然。不出于如。如优波离。以心相得解脱时。宁有垢不。我言。不也。维摩诘言。一切众生心相无垢亦复如是。唯优波离。妄想是垢无妄想是净。颠倒是垢。无颠倒是净。取我是垢。不取我是净。优波离。一切法生灭不住。如幻如电诸法不相待。乃至一念不住。诸法皆妄见。如梦如炎如水中月如镜中像以妄想生。其知此者是名奉律。其知此者是名善解。</p><p class="su-tra">佛告诉优波离：“你到维摩诘那里问疾。”优波离对佛说：“世尊，我不能胜任去向他问疾。为什么呢？回忆从前有两位比丘犯戒，心中以为耻，不敢问佛，来问我：‘唯优波离，我们犯戒，实在以为耻，不敢问佛，愿解除疑悔，得以免除此罪咎。’我即为他们如法解说，维摩诘来对我说：‘唯优波离，不要更加重这二位比丘的罪，应当直接除灭，不要扰乱他们的心。为什么呢？彼罪性不在内、不在外、不在中间。如佛所说，心垢故众生垢，心净故众生净；心也不在内、不在外、不在中间。如其心然，罪垢也是如此，诸法也是如此，都不出于如。优波离，当心从相中得解脱时，难道还有垢吗？’我说：‘没有。’维摩诘说：‘一切众生心相无垢，也是如此。唯优波离，妄想是垢，无妄想是净；颠倒是垢，无颠倒是净；取我是垢，不取我是净。优波离，一切法生灭不住，如幻、如电，诸法不相依赖，乃至一念也不住；诸法都是妄见，如梦、如阳焰、如水中月、如镜中像，由妄想而生。了知这一点的，名为奉持律法；了知这一点的，名为善解律法。’”</p></div><div class="su-pair"><p class="su-org">于是二比丘言。上智哉。是优波离所不能及。持律之上而不能说。我即答言。自舍如来未有声闻及菩萨能制其乐说之辩。其智慧明达为若此也。时二比丘疑悔即除。发阿耨多罗三藐三菩提心。作是愿言。令一切众生皆得是辩。故我不任诣彼问疾。</p><p class="su-tra">于是二位比丘说：“真是上上的智慧！这是优波离所不能及的。他是持律的上首，却不能这样解说。”我便回答：“除了如来，未曾有声闻及菩萨能与他这样的乐说辩才相比，他的智慧明达到这种地步。”二位比丘的疑悔当即除灭，发阿耨多罗三藐三菩提心，作这样的愿：“令一切众生皆得这样的辩才。”所以不能胜任去向他问疾。</p></div><div class="su-pair"><p class="su-org">佛告罗睺罗。汝行诣维摩诘问疾。罗睺罗白佛言。世尊。我不堪任诣彼问疾。所以者何。忆念昔时毘耶离诸长者子。来诣我所稽首作礼问我言。唯罗睺罗。汝佛之子。舍转轮王位出家为道。其出家者有何等利。我即如法为说出家功德之利。时维摩诘来谓我言。唯罗睺罗。不应说出家功德之利。所以者何。无利无功德是为出家。有为法者可说有利有功德。夫出家者为无为法。无为法中无利无功德。罗睺罗。出家者无彼无此亦无中间。离六十二见处于涅槃。智者所受圣所行处。降伏众魔度五道。净五眼得五力立五根。不恼于彼。离众杂恶摧诸外道。超越假名出淤泥。无系著无我所。无所受无扰乱。内怀喜护彼意。随禅定离众过。若能如是是真出家。于是维摩诘语诸长者子。汝等于正法中宜共出家。所以者何。佛世难值。诸长者子言。居士。我闻佛言。父母不听不得出家。维摩诘言。然汝等便发阿耨多罗三藐三菩提心是即出家。是即具足。尔时三十二长者子。皆发阿耨多罗三藐三菩提心。故我不任诣彼问疾。</p><p class="su-tra">佛告诉罗睺罗：“你到维摩诘那里问疾。”罗睺罗对佛说：“世尊，我不能胜任去向他问疾。为什么呢？回忆从前毗耶离诸长者之子来到我这里，稽首作礼，问我：‘唯罗睺罗，你是佛之子，舍弃转轮王位出家为道，这出家有什么利益？’我即如法为他们说出家功德之利。维摩诘来对我说：‘唯罗睺罗，不应说出家功德之利。为什么呢？无利无功德，这才是出家。有为法才可说有利、有功德；出家所行的是无为法，无为法中没有利、没有功德。罗睺罗，出家者无彼、无此，也无中间；远离六十二见而处于涅槃；是智者所受、圣人所行之处；降伏众魔，度脱五道；净五眼，得五力，立五根；不扰乱他人，远离众杂恶，摧伏诸外道；超越假名而出淤泥；无所系著，无我所，无所受，无扰乱；内心怀喜而护持他人之意；随顺禅定而远离众过。若能如此，才是真正的出家。’于是维摩诘对诸长者之子说：‘你们在正法中应共同出家。为什么呢？佛世难值。’诸长者之子说：‘居士，我们听佛说，父母不听许，不得出家。’维摩诘说：‘这样，你们便发阿耨多罗三藐三菩提心，这即是出家，即是具足。’那时三十二位长者之子都发阿耨多罗三藐三菩提心，所以不能胜任去向他问疾。”</p></div><div class="su-pair"><p class="su-org">佛告阿难。汝行诣维摩诘问疾。阿难白佛言。世尊。我不堪任诣彼问疾。所以者何。忆念昔时世尊身小有疾当用牛乳。我即持钵诣大婆罗门家门下立。时维摩诘来谓我言。唯阿难。何为晨朝持钵住此。我言。居士。世尊身小有疾当用牛乳。故来至此。维摩诘言。止止阿难。莫作是语。如来身者金刚之体。诸恶已断众善普会。当有何疾当有何恼。默往阿难。勿谤如来。莫使异人闻此麁言。无令大威德诸天及他方净土诸来菩萨得闻斯语。阿难。转轮圣王以少福故尚得无病。岂况如来无量福会普胜者哉。行矣阿难。勿使我等受斯耻也。外道梵志若闻此语当作是念。何名为师。自疾不能救而能救诸疾。仁可密速去勿使人闻。当知阿难。诸如来身即是法身非思欲身。佛为世尊过于三界。佛身无漏诸漏已尽。佛身无为不堕诸数。如此之身当有何疾当有何恼。时我世尊实怀惭愧。得无近佛而谬听耶。即闻空中声曰。阿难。如居士言。但为佛出五浊恶世。现行斯法度脱众生。行矣阿难。取乳勿惭。世尊。维摩诘智慧辩才为若此也。是故不任诣彼问疾。如是五百大弟子。各各向佛说其本缘。称述维摩诘所言。皆曰不任诣彼问疾。</p><p class="su-tra">佛告诉阿难：“你到维摩诘那里问疾。”阿难对佛说：“世尊，我不能胜任去向他问疾。为什么呢？回忆从前世尊身体稍有疾病，当用牛乳，我便持钵到大婆罗门家门前站立。维摩诘来对我说：‘唯阿难，为何清晨持钵住在这里？’我说：‘居士，世尊身体稍有疾病，当用牛乳，所以来到这里。’维摩诘说：‘止止，阿难，莫作此语。如来之身是金刚之体，诸恶已断，众善普会，当有什么疾病、什么烦恼？默然去吧，阿难，不要诽谤如来，不要让异人听到这般粗话，不要让有大威德的诸天及他方净土前来的菩萨听到此语。阿难，转轮圣王以较少福德，尚且能得无病，何况如来是无量福德集会、普胜一切呢？去吧，阿难，不要让我们受此耻辱。外道梵志若闻此语，会这样想：这名为师父的人，自己有病不能救，还能救诸病吗？你可秘密速去，不要使人听到。当知阿难，诸如来身即是法身，不是思欲之身；佛为世尊，超过三界；佛身无漏，诸漏已尽；佛身无为，不堕于诸数。这样的身体，当有什么疾病、什么烦恼？’世尊，我当时实在惭愧，难道我亲近佛陀，竟会听错吗？随即听到空中的声音：‘阿难，如居士所言。只是因为佛出现于五浊恶世，现行此法以度脱众生。去吧，阿难，取乳不要惭愧。’世尊，维摩诘的智慧辩才达到这种地步，所以不能胜任去向他问疾。如是五百位大弟子，各各向佛诉说自己的本缘，称述维摩诘所言，都说不能胜任去向他问疾。”</p></div><h3 class="su-sec">菩萨品第四</h3><div class="su-pair"><p class="su-org">于是佛告弥勒菩萨。汝行诣维摩诘问疾。弥勒白佛言。世尊。我不堪任诣彼问疾。所以者何。忆念我昔为兜率天王及其眷属。说不退转地之行。时维摩诘来谓我言。弥勒。世尊授仁者记一生当得阿耨多罗三藐三菩提。为用何生得受记乎。过去耶未来耶现在耶。若过去生过去生已灭。若未来生未来生未至。若现在生现在生无住。如佛所说。比丘汝今即时亦生亦老亦灭。若以无生得受记者。无生即是正位。于正位中亦无受记。亦无得阿耨多罗三藐三菩提。云何弥勒受一生记乎。为从如生得受记耶。为从如灭得受记耶。若以如生得受记者如无有生。若以如灭得受记者如无有灭。一切众生皆如也。一切法亦如也。众圣贤亦如也。至于弥勒亦如也。若弥勒得受记者。一切众生亦应受记。所以者何。夫如者不二不异。若弥勒得阿耨多罗三藐三菩提者。一切众生皆亦应得。所以者何。一切众生即菩提相。若弥勒得灭度者。一切众生亦应灭度。所以者何。诸佛知一切众生毕竟寂灭即涅槃相不复更灭。是故弥勒。无以此法诱诸天子。实无发阿耨多罗三藐三菩提心者。亦无退者。弥勒当令此诸天子舍于分别菩提之见。所以者何。菩提者。不可以身得。不可以心得。寂灭是菩提。灭诸相故。不观是菩提离诸缘故。不行是菩提无忆念故。断是菩提舍诸见故。离是菩提离诸妄想故。障是菩提障诸愿故。不入是菩提无贪著故。顺是菩提顺于如故。住是菩提住法性故。至是菩提至实际故。不二是菩提离意法故。等是菩提等虚空故。无为是菩提无生住灭故。知是菩提了众生心行故。不会是菩提诸入不会故。不合是菩提离烦恼习故。无处是菩提无形色故。假名是菩提名字空故。如化是菩提无取舍故。无乱是菩提常自静故。善寂是菩提性清净故。无取是菩提离攀缘故。无异是菩提诸法等故。无比是菩提无可喻故。微妙是菩提诸法难知故。世尊。维摩诘说是法时。二百天子得无生法忍。故我不任诣彼问疾。</p><p class="su-tra">于是佛告诉弥勒菩萨：“你到维摩诘那里问疾。”弥勒对佛说：“世尊，我不能胜任去向他问疾。为什么呢？回忆我从前为兜率天王及其眷属，说不退转地之行。维摩诘来对我说：‘弥勒，世尊授你之记，说你一生当得阿耨多罗三藐三菩提。你是用哪一生得受记呢？过去生、未来生，还是现在生？若过去生，过去生已灭；若未来生，未来生未至；若现在生，现在生无住。如佛所说，比丘，你现今即时也在生、也在老、也在灭。若以无生得受记，无生即是正位；于正位中，也无受记，也无得阿耨多罗三藐三菩提。弥勒，你如何受一生之记呢？是从如的生而得受记吗？是从如的灭而得受记吗？若以如生得受记，如无有生；若以如灭得受记，如无有灭。一切众生皆如，一切法亦如，众圣贤亦如，至于弥勒亦如。若弥勒得受记，一切众生也应受记。为什么呢？如者不二不异。若弥勒得阿耨多罗三藐三菩提，一切众生也都应得。为什么呢？一切众生即是菩提之相。若弥勒得灭度，一切众生也应灭度。为什么呢？诸佛知一切众生毕竟寂灭，即是涅槃之相，不再更灭。因此，弥勒，不要以此法诱惑诸天子。实际上无发阿耨多罗三藐三菩提心者，也无退转者。弥勒，当令这些天子舍弃分别菩提之见。为什么呢？菩提不可以身得，不可以心得。寂灭是菩提，因为灭除诸相；不观是菩提，因为远离诸缘；不行是菩提，因为无忆念；断是菩提，因为舍弃诸见；离是菩提，因为远离诸妄想；障是菩提，因为障蔽诸愿；不入是菩提，因为无贪著；顺是菩提，因为顺于如；住是菩提，因为住于法性；至是菩提，因为至于实际；不二是菩提，因为离于意与法；等是菩提，因为等同虚空；无为是菩提，因为无生、住、灭；知是菩提，因为了知众生心行；不会是菩提，因为诸入不会；不合是菩提，因为远离烦恼习气；无处是菩提，因为无形色；假名是菩提，因为名字空寂；如化是菩提，因为无取舍；无乱是菩提，因为常自寂静；善寂是菩提，因为性清净；无取是菩提，因为远离攀缘；无异是菩提，因为诸法平等；无比是菩提，因为无可比拟；微妙是菩提，因为诸法难知。’世尊，维摩诘说此法时，二百位天子得无生法忍，所以不能胜任去向他问疾。”</p></div><div class="su-pair"><p class="su-org">佛告光严童子。汝行诣维摩诘问疾。光严白佛言。世尊。我不堪任诣彼问疾。所以者何。忆念我昔出毘耶离大城。时维摩诘方入城。我即为作礼而问言。居士从何所来。答我言。吾从道场来。我问道场者何所是。答曰。直心是道场无虚假故。发行是道场能办事故。深心是道场增益功德故。菩提心是道场无错谬故。布施是道场不望报故。持戒是道场得愿具故。忍辱是道场于诸众生心无碍故。精进是道场不懈退故。禅定是道场心调柔故。智慧是道场现见诸法故。慈是道场等众生故。悲是道场忍疲苦故。喜是道场悦乐法故。舍是道场憎爱断故。神通是道场成就六通故。解脱是道场能背舍故。方便是道场教化众生故。四摄是道场摄众生故。多闻是道场如闻行故。伏心是道场正观诸法故。三十七品是道场舍有为法故。谛是道场不诳世间故。缘起是道场无明乃至老死皆无尽故。诸烦恼是道场知如实故。众生是道场知无我故。一切法是道场知诸法空故。降魔是道场不倾动故。三界是道场无所趣故。师子吼是道场无所畏故。力无畏不共法是道场无诸过故。三明是道场无余碍故。一念知一切法是道场成就一切智故。如是善男子。菩萨若应诸波罗蜜教化众生。诸有所作举足下足。当知皆从道场来住于佛法矣。说是法时五百天人皆发阿耨多罗三藐三菩提心。故我不任诣彼问疾。佛告持世菩萨。汝行诣维摩诘问疾。持世白佛言。世尊。我不堪任诣彼问疾。所以者何。忆念我昔住于静室。时。魔波旬从万二千天女。状如帝释鼓乐弦歌来诣我所。与其眷属稽首我足。合掌恭敬于一面立。我意谓是帝释。而语之言。善来憍尸迦。虽福应有不当自恣。当观五欲无常以求善本。于身命财而修坚法。即语我言。正士。受是万二千天女可备扫洒。我言。憍尸迦。无以此非法之物要我沙门释子此非我宜。所言未讫时维摩诘来谓我言。非帝释也。是为魔来娆固汝耳。即语魔言。是诸女等可以与我。如我应受。魔即惊惧念。维摩诘将无恼我。欲隐形去而不能隐。尽其神力亦不得去。即闻空中声曰。波旬。以女与之乃可得去。魔以畏故俛仰而与。</p><p class="su-tra">佛告诉光严童子：“你到维摩诘那里问疾。”光严对佛说：“世尊，我不能胜任去向他问疾。为什么呢？回忆我从前出毗耶离大城，维摩诘正入城，我即向他作礼而问：‘居士从何处来？’他回答：‘我从道场来。’我问：‘道场是什么地方？’他回答：‘直心是道场，因为没有虚假；发行是道场，因为能成就事业；深心是道场，因为能增益功德；菩提心是道场，因为没有错谬；布施是道场，因为不望回报；持戒是道场，因为能得愿具足；忍辱是道场，因为于诸众生心无挂碍；精进是道场，因为不懈怠退转；禅定是道场，因为心调柔；智慧是道场，因为能现见诸法；慈是道场，因为平等对待众生；悲是道场，因为能忍受疲劳苦痛；喜是道场，因为悦乐于法；舍是道场，因为断除憎爱；神通是道场，因为成就六通；解脱是道场，因为能背舍；方便是道场，因为能教化众生；四摄是道场，因为能摄受众生；多闻是道场，因为能如所闻而行；伏心是道场，因为能正观诸法；三十七道品是道场，因为能舍弃有为法；谛是道场，因为不欺诳世间；缘起是道场，因为无明乃至老死皆无尽；诸烦恼是道场，因为能如实了知；众生是道场，因为能知无我；一切法是道场，因为能知诸法空；降魔是道场，因为不倾动；三界是道场，因为无所趣向；狮子吼是道场，因为无所畏惧；力、无畏、不共法是道场，因为无诸过失；三明是道场，因为无有余碍；一念知一切法是道场，因为能成就一切智。如是，善男子，菩萨若应以诸波罗蜜教化众生，那么诸有所作，举足下足，当知都从道场而来，住于佛法。’说此法时，五百位天人皆发阿耨多罗三藐三菩提心，所以不能胜任去向他问疾。”佛告诉持世菩萨：“你到维摩诘那里问疾。”持世对佛说：“世尊，我不能胜任去向他问疾。为什么呢？回忆我从前住在静室，魔王波旬带着一万二千位天女，状如帝释，鼓乐弦歌，来到我这里。他和眷属稽首我的足，合掌恭敬地站在一面。我以为他是帝释，便说：‘欢迎你，憍尸迦！你虽有福德，不应自行放纵，应当观察五欲无常，以求善本；于身、命、财而修坚法。’他随即说：‘正士，请接受这一万二千位天女，可供打扫洒水。’我说：‘憍尸迦，不要用这些非法之物要我沙门释子，这不是我所适宜的。’话音未落，维摩诘来对我说：‘他不是帝释，是魔王来扰乱、诱惑你。’又对魔王说：‘这些女子可以给我，如我所应受。’魔王当即惊惧，心想维摩诘恐怕要恼害我，想隐形而去却不能隐，竭尽神力也离开不了。随即听到空中的声音：‘波旬，把她们交给他，才可以离去。’魔王因恐惧便把她们交给了他。”</p></div><div class="su-pair"><p class="su-org">尔时维摩诘语诸女言。魔以汝等与我。今汝皆当发阿耨多罗三藐三菩提心。即随所应而为说法令发道意。复言。汝等已发道意。有法乐可以自娱。不应复乐五欲乐也。天女即问。何谓法乐。答言。乐常信佛。乐欲听法。乐供养众。乐离五欲。乐观五阴如怨贼。乐观四大如毒蛇。乐观内入如空聚。乐随护道意。乐饶益众生。乐敬养师。乐广行施。乐坚持戒。乐忍辱柔和。乐勤集善根。乐禅定不乱。乐离垢明慧。乐广菩提心。乐降伏众魔。乐断诸烦恼。乐净佛国土。乐成就相好故修诸功德。乐严道场。乐闻深法不畏。乐三脱门不乐非时。乐近同学。乐于非同学中心无恚碍。乐将护恶知识。乐亲近善知识。乐心喜清净。乐修无量道品之法。是为菩萨法乐。</p><p class="su-tra">这时维摩诘对诸女子说：“魔王把你们给了我，现在你们都应当发阿耨多罗三藐三菩提心。”于是随其所应而为说法，令她们发起道意。又说：“你们已发道意，有法乐可以自娱，不应再乐于五欲之乐。”天女们问：“什么是法乐？”他回答说：“乐于常信佛，乐于听法，乐于供养大众，乐于远离五欲；乐于观察五阴如怨贼，四大如毒蛇，内入如空聚；乐于随顺护持道意，乐于饶益众生，乐于敬养师长，乐于广行布施，乐于坚持戒律，乐于忍辱柔和，乐于勤集善根，乐于禅定不乱，乐于远离尘垢而明慧，乐于广发菩提心，乐于降伏众魔，乐于断除诸烦恼，乐于清净佛国土，乐于成就相好而修诸功德，乐于庄严道场，乐于听闻深法而不畏惧，乐于三种解脱法门而不耽于不合时宜之事，乐于亲近同学，乐于在非同学中而心无嗔恚障碍，乐于护持恶知识，乐于亲近善知识，乐于心喜清净，乐于修习无量道品之法。这就是菩萨法乐。”</p></div><div class="su-pair"><p class="su-org">于是波旬告诸女言。我欲与汝俱还天宫。诸女言。以我等与此居士。有法乐我等甚乐。不复乐五欲乐也。魔言。居士可舍此女。一切所有施于彼者。是为菩萨。维摩诘言。我已舍矣。汝便将去。令一切众生得法愿具足。于是诸女问维摩诘。我等云何止于魔宫。维摩诘言。诸姊有法门名无尽灯。汝等当学。无尽灯者。譬如一灯燃百千灯。冥者皆明。明终不尽。如是诸姊。夫一菩萨开导百千众生。令发阿耨多罗三藐三菩提心。于其道意亦不灭尽。随所说法而自增益一切善法。是名无尽灯也。汝等虽住魔宫。以是无尽灯。令无数天子天女发阿耨多罗三藐三菩提心者。为报佛恩。亦大饶益一切众生。尔时天女。头面礼维摩诘足。随魔还宫忽然不现。世尊。维摩诘有如是自在神力智慧辩才。故我不任诣彼问疾。</p><p class="su-tra">于是魔王告诉诸女子：“我想与你们一同返回天宫。”诸女子说：“既然你把我们给了这位居士，我们有法乐，十分快乐，不再乐于五欲之乐。”魔王说：“居士，可以舍弃这些女子。凡一切施予他的所有物，他都布施出去，这才称为菩萨。”维摩诘说：“我已经舍弃了，你便带她们去吧，令一切众生得法愿具足。”于是诸女子问维摩诘：“我们如何安住于魔宫？”维摩诘说：“诸位姐姐，有个法门名叫无尽灯，你们应当修学。无尽灯，譬如一灯点燃百千盏灯，黑暗之处全都明亮，而光明终究不尽。如是，诸姊，一位菩萨开导百千众生，令他们发阿耨多罗三藐三菩提心，他们的道意也不灭尽；随所说法，菩萨自己又增益一切善法，这名叫无尽灯。你们虽住于魔宫，以这无尽灯，令无数天子天女发阿耨多罗三藐三菩提心，是为报答佛恩，也大大饶益一切众生。”那时天女以头面礼维摩诘足，随魔王返回天宫，忽然不现。“世尊，维摩诘有如是自在神力、智慧辩才，所以不能胜任去向他问疾。”</p></div><div class="su-pair"><p class="su-org">佛告长者子善德。汝行诣维摩诘问疾。善德白佛言。世尊我不堪任诣彼问疾。所以者何。忆念我昔自于父舍设大施会。供养一切沙门婆罗门及诸外道贫穷下贱孤独乞人。期满七日。时维摩诘来入会中。谓我言。长者子。夫大施会不当如汝所设。当为法施之会。何用是财施会为。我言。居士。何谓法施之会。答曰。法施会者。无前无后一时供养一切众生。是名法施之会。曰何谓也。谓以菩提起于慈心。以救众生。起大悲心。以持正法起于喜心。以摄智慧行于舍心。以摄悭贪起檀波罗蜜。以化犯戒起尸罗波罗蜜。以无我法起羼提波罗蜜。以离身心相起毘梨耶波罗蜜。以菩提相起禅波罗蜜。以一切智起般若波罗蜜。教化众生而起于空。不舍有为法而起无相。示现受生而起无作。护持正法起方便力。以度众生起四摄法。以敬事一切起除慢法。于身命财起三坚法。于六念中。起思念法。于六和敬起质直心。正行善法起于净命。心净欢喜起近贤圣。不憎恶人起调伏心。以出家法起于深心。以如说行起于多闻。以无诤法起空闲处。趣向佛慧起于宴坐。解众生缚起修行地。以具相好及净佛土起福德业。知一切众生心念如应说法起于智业。知一切法不取不舍。入一相门起于慧业。断一切烦恼一切障碍一切不善法起一切善业以得一切智慧一切善法。起于一切助佛道法。如是善男子。是为法施之会。若菩萨住是法施会者。为大施主。亦为一切世间福田。世尊。维摩诘说是法时。婆罗门众中二百人皆发阿耨多罗三藐三菩提心。我时心得清净叹未曾有。稽首礼维摩诘足。即解璎珞价直百千。以上之。不肯取。我言居士。愿必纳受随意所与。维摩诘乃受璎珞分作二分。持一分施此会中一最下乞人。持一分奉彼难胜如来。一切众会皆见光明国土难胜如来。又见珠璎在彼佛上变成四柱宝台四面严饰不相障蔽。时维摩诘。现神变已作是言。若施主等心施一最下乞人。犹如如来福田之相无所分别。等于大悲不求果报。是则名曰具足法施。城中一最下乞人。见是神力闻其所说。皆发阿耨多罗三藐三菩提心。故我不任诣彼问疾。如是诸菩萨各各向佛说其本缘。称述维摩诘所言。皆曰不任诣彼问疾。</p><p class="su-tra">佛告诉长者之子善德：“你到维摩诘那里问疾。”善德对佛说：“世尊，我不能胜任去向他问疾。为什么呢？回忆我从前在父家设大施会，供养一切沙门、婆罗门及诸外道，以及贫穷、下贱、孤独、乞讨之人，期满七日。维摩诘来到会中，对我说：‘长者子，大施会不应像你这样设，应当设法施之会，何必用这财施会呢？’我说：‘居士，什么是法施之会？’他回答：‘法施会，无前无后，一时供养一切众生，这名叫法施之会。’我说：‘什么意思呢？’他说：‘以菩提心起于慈心，以救度众生而起大悲心，以受持正法而起喜心，以摄持智慧而行舍心；以摄伏悭贪而起布施波罗蜜，以教化犯戒者而起持戒波罗蜜，以无我法而起忍辱波罗蜜，以远离身心之相而起精进波罗蜜，以菩提之相而起禅定波罗蜜，以一切智而起般若波罗蜜；以教化众生而起于空，以不舍有为法而起无相，以示现受生而起无作；以护持正法而起方便力，以度化众生而起四摄法；以敬事一切而起除慢法，于身、命、财而起三种坚法；于六念中而起思念法，于六和敬而起质直心；以正行善法而起于净命，以心净欢喜而起近贤圣，以不憎恶人而起调伏心；以出家法而起深心，以如说而行而起多闻，以无诤法而起空闲处，以趣向佛慧而起宴坐；以解除众生缠缚而起修行地，以具足相好及清净佛土而起福德业；以了知一切众生心念、如应说法而起智业；以了知一切法不取不舍、入一相门而起慧业；以断除一切烦恼、一切障碍、一切不善法而起一切善业，以得一切智慧、一切善法，以起一切助佛道之法。如是，善男子，这就是法施之会。若菩萨住于这法施会，就是大施主，也是一切世间的福田。’世尊，维摩诘说此法时，婆罗门众中有二百人皆发阿耨多罗三藐三菩提心。我当时心得清净，赞叹前所未有，稽首礼维摩诘足，随即解下价值百千的璎珞献给他，他不肯取。我说：‘居士，愿你一定纳受，随意使用所施之物。’维摩诘于是接受璎珞，分成两份，以一份施给会中一位最下贱的乞人，以一份奉给难胜如来。一切法会大众都看见光明国土中的难胜如来，又看见珠璎在彼佛身上变成四柱宝台，四面庄严，彼此不相障蔽。维摩诘显现神变后说：‘若施主以平等心施给一位最下贱的乞人，犹如如来福田之相，无所分别；等同大悲而不求果报，这名叫具足法施。’城中一位最下贱的乞人见此神力、闻其所说，也发阿耨多罗三藐三菩提心，所以不能胜任去向他问疾。如是诸菩萨各各向佛诉说自己的本缘，称述维摩诘所言，都说不能胜任去向他问疾。”</p></div></div></div>',4)])])}const n=a(i,[["render",l]]);export{g as __pageData,n as default};
